/**
 * Label-sourced contraindication pins for named CYP pairs.
 *
 * Why this exists: the enzyme rule (`pkSeverity` in engine.ts) grades pairs
 * from perpetrator strength and substrate sensitivity. For a short list of
 * pairs, the FDA-approved label itself lists the combination under
 * Contraindications. Those pairs should read "Avoid together" because the
 * label says so, not only because the enzyme grades happen to line up. When a
 * perpetrator grade is corrected to FDA's table (for example ciprofloxacin as a
 * moderate CYP1A2 inhibitor), the enzyme rule alone can drop a
 * label-contraindicated pair. A pin keeps it at contraindicated.
 *
 * Scope rules:
 * - Only exact, named catalog pairs. No class expansion, no global threshold
 *   change. Each pin names one enzyme and one direction (inhibitor or inducer).
 * - `quote`, `labelExample`, `labelSection` and `url` are copied byte-for-byte
 *   from `src/lib/drugs/reference/label-gold-set.ts` (PR #65), so the desk and
 *   the gold-set test cite identical text. Quotes are verbatim DailyMed SPL
 *   text ("…" marks an elided span), retrieved 2026-09-27.
 * - Rows with origin "wave3" copy the same fields byte-for-byte from PR #75
 *   (`feat/label-gold-wave3`, commit f41256d). Those quotes were retrieved
 *   2026-10-02. They pin pairs that already produce a CYP3A4 finding below
 *   contraindicated.
 * - Rows with origin "wave4" copy the same fields byte-for-byte from PR #86
 *   (`feat/label-gold-wave4`, commit 5912f77). Those quotes were retrieved
 *   2026-10-02. They hold an existing enzyme finding (below contraindicated
 *   on main) at contraindicated. One enzyme and one direction, the finding
 *   the pair already produces.
 * - Rows with origin "no-enzyme" copy the same fields from the wave-3 or
 *   wave-4 gold set and omit `enzyme` and `kind`. The desk emits a standalone
 *   contraindicated finding and does not invent a CYP grade. Wave 3 is the
 *   seven pairs whose partner has no CYP role the engine uses (elbasvir/
 *   grazoprevir, irinotecan, drospirenone; irinotecan is UGT1A1, not a CYP).
 *   Wave 4 adds pairs that show no enzyme finding: itraconazole with
 *   dofetilide and irinotecan, Kaletra with elbasvir/grazoprevir, and
 *   Paxlovid with flecainide, phenytoin, rifapentine, and the inducers whose
 *   only row today is a washout clock.
 * - Rows with origin "restored-after-58" are not in the gold set. Their quotes
 *   reuse gold-set strings where the same label sentence applies, or are the
 *   verbatim DailyMed Contraindications text (Ranexa section 4).
 * - `contraindicationsSentence` is added only where the gold-set quote comes
 *   from a section other than Contraindications (Zanaflex 7.1, Ranexa 7.1). It
 *   is the verbatim section 4 sentence from the same DailyMed label.
 * - Leftover wave-1 gold pairs (still below contraindicated after the wave-4
 *   pins) copy `quote`, `labelSection`, and the DailyMed link byte-for-byte
 *   from label-gold-set.ts as of a79b09b. Each pin names the enzyme finding
 *   the pair already produces.
 * - Rows with origin "pd" copy quote, labelDrug, labelSection, and the
 *   DailyMed link from the wave-2 gold rows (retrieved 2026-09-27). They omit
 *   enzyme and kind. The desk holds the existing pharmacodynamic finding at
 *   contraindicated. It does not add a CYP grade and it does not add a second
 *   card. Naltrexone is pinned with methadone, buprenorphine, oxycodone, or
 *   hydrocodone only. Wave 5 Geodon pairs use the same path when a
 *   pharmacodynamic card already exists, and the no-enzyme path when none
 *   does. Other naltrexone + opioid pairs are not pinned.
 * - 91 more "wave3" (41) and "wave4" (50) rows close the former
 *   KNOWN_CONTRAINDICATION_GAPS list: gold pairs whose label says contraindicated
 *   and that read contraindicated only through the enzyme rule, which Ship 1.51
 *   (7bdfa95) capped at major. They hold the existing CYP3A4 finding with the
 *   labeled product as the perpetrator. No new CYP grade.
 * - Rows with origin "wave6" are Recorlev (levoketoconazole) pairs from the
 *   current DailyMed SPL (setid d4c5fead-bc4a-fb02-e053-2a95a90ae4fc,
 *   retrieved 2026-10-05). Section 4 contraindicates drugs that cause QT
 *   prolongation associated with ventricular arrhythmias. Table 6 (section
 *   7.1) says that use is contraindicated and names the drugs. Only catalog
 *   drugs named there are pinned. The pair has no pharmacodynamic card, so
 *   the pin holds the CYP3A4 finding the pair already produces, with
 *   levoketoconazole as the perpetrator (the wave-3 Korlym orientation). No
 *   new CYP grade. Dofetilide has no finding and uses the no-enzyme path.
 *   Table 6's sensitive-substrate row says "contraindicated or not
 *   recommended" without saying which, so those drugs are not pinned.
 * - Wave 12 rows (retrieved 2026-10-19, origin "pd") close two of the 21
 *   unsourced Avoid together grades in docs/grade-provenance-audit.md: Parnate
 *   Table 1 (4.1) names tryptophan and hydroxytryptophan, and the Marplan
 *   CONTRAINDICATIONS sentence names foods with a high tyramine content.
 * - Wave 14 rows (retrieved 2026-10-19, origin "pd") copy quote, labelSection,
 *   labelExample and the DailyMed link byte-for-byte from the wave-14 gold rows:
 *   Marplan CONTRAINDICATIONS with meperidine, fluoxetine, cocaine and the
 *   named MAOI and tricyclic list. Each pair card already read Avoid together.
 * - Wave 13 rows (retrieved 2026-10-19, origin "pd") copy quote, labelSection,
 *   labelExample and the DailyMed link byte-for-byte from the wave-13 gold
 *   rows: Parnate Table 1 (4.1) with dextromethorphan, SAM-e, amoxapine,
 *   dopamine, pseudoephedrine, phenylephrine and ephedrine; Nardil
 *   CONTRAINDICATIONS with tyramine foods and L-tryptophan. Each pair card
 *   already read Avoid together.
 * - Wave 16 rows (retrieved 2026-10-28, origin "pd") copy quote, labelSection,
 *   labelExample and the DailyMed link byte-for-byte from the wave-16 gold
 *   rows: Nitrostat 4.1 with avanafil, sildenafil, tadalafil and vardenafil;
 *   isosorbide dinitrate CONTRAINDICATIONS with sildenafil, tadalafil and
 *   vardenafil; febuxostat 4 with azathioprine and mercaptopurine; disulfiram
 *   CONTRAINDICATIONS with alcohol. Each pair card already read Avoid together.
 * - Wave 7 rows (retrieved 2026-10-12) copy quote, labelSection, labelExample
 *   and the DailyMed link byte-for-byte from the wave-7 gold rows. Every quote
 *   is section 4 (Contraindications) text from Tikosyn, Tracleer, Adempas,
 *   Xenazine, Austedo, Mavyret, Edurant, Biktarvy, Tivicay, Apokyn, Relpax,
 *   Vosevi or Bixlenvo, and each partner is named there. Origin "wave7" holds the CYP
 *   finding the pair already produces (inducer or inhibitor, either
 *   orientation). Pairs with a pharmacodynamic card use "pd"; pairs with no
 *   finding use "no-enzyme". No new CYP grade. Adempas with sildenafil,
 *   tadalafil and vardenafil use "pd": the engine adds a riociguat x PDE5
 *   hypotension card, and the pin holds it at contraindicated.
 *   Wave 7 second pass (gold-wave-8) adds 44 named section 4 pairs from
 *   Zokinvy, pimozide, triazolam, Tegretol, ranolazine, Cafergot,
 *   dihydroergotamine, Latuda, Inspra, Multaq, Movantik, bupropion, Contrave,
 *   Tikosyn, thioridazine and Revatio. Same three origins, no new CYP grade.
 *   Braftovi and Etcamah list no contraindications; Lifyorli names no drug.
 *
 * Educational reference, not FDA-cleared. No doses.
 */
import type { Enzyme } from "./types";

export interface LabelContraindication {
  /** Stable id, `labelDrugId+otherId` (matches the gold-set id). */
  id: string;
  /** Catalog id of the drug whose label carries the contraindication. */
  labelDrugId: string;
  /** Catalog id of the other drug (the CYP perpetrator). */
  otherId: string;
  /**
   * Enzyme the pinned finding is on. Omitted when there is no enzyme finding
   * to hold. Origin "no-enzyme" then emits a standalone contraindicated
   * finding. Origin "pd" holds the existing pharmacodynamic finding instead.
   * Neither assigns a CYP grade.
   */
  enzyme?: Enzyme;
  /** Direction of the perpetrator on that enzyme. Omitted together with `enzyme`. */
  kind?: "inhibitor" | "inducer";
  labelDrug: string;
  labelSection: string;
  quote: string;
  labelExample?: string;
  contraindicationsSentence?: string;
  url: string;
  /**
   * `named`: the label names this drug (in the Contraindications sentence or
   * the example list it points to). `class`: the Contraindications sentence
   * covers a class this drug belongs to (for example "inducers of CYP3A") but
   * does not name it.
   */
  basis: "named" | "class";
  /** Why the pin was added: gold-set pair from PR #65 (including leftover wave-1 pairs pinned later), restored after PR #58 grade changes, a #75 wave-3 pair that still read below contraindicated, a #86 wave-4 pair whose existing enzyme finding is held at contraindicated, a pair with no enzyme finding to hold, a pharmacodynamic finding held at contraindicated (naltrexone with a labeled opioid), or a Recorlev Table 6 QT pair whose existing CYP3A4 finding is held at contraindicated (wave 6). */
  origin: "gold-set" | "restored-after-58" | "wave3" | "wave4" | "no-enzyme" | "pd" | "wave6" | "wave7";
  /**
   * DailyMed retrieval date for this quote when it is not
   * `LABEL_CONTRAINDICATIONS_RETRIEVED` (wave 3 is 2026-10-02; Recorlev is 2026-10-05).
   */
  retrieved?: "2026-10-02" | "2026-10-03" | "2026-10-05" | "2026-10-12" | "2026-10-19" | "2026-10-28";
}

export const LABEL_CONTRAINDICATIONS_RETRIEVED = "2026-09-27";

// Recorlev (levoketoconazole) tablets. DailyMed SPL version 13, effective 2026-03-10, published 2026-06-26.
const RECORLEV_URL = "https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=d4c5fead-bc4a-fb02-e053-2a95a90ae4fc";
/** Table 6 (section 7.1), row "CYP3A4 or CYP3A4 and P-gp Substrates That May Prolong QT". */
const RECORLEV_QT =
  "Concomitant use of RECORLEV with other drugs that cause QT prolongation associated with ventricular arrhythmias, including torsades de pointes, is contraindicated";
/** Section 4, verbatim; "…" elides the first (hepatic) item of the list. */
const RECORLEV_CI_QT =
  "RECORLEV is contraindicated in patients: … Taking drugs that cause QT prolongation associated with ventricular arrhythmias, including torsades de pointes";

