export const LABEL_CONTRAINDICATED_TAG = "label-contraindicated";

const BY_PAIR = new Map<string, LabelContraindication>();
for (const r of LABEL_CONTRAINDICATIONS) {
  BY_PAIR.set([r.labelDrugId, r.otherId].sort().join("|"), r);
}

/** Pin for an unordered pair of catalog ids, if the label contraindicates it. */
export function labelContraindicationFor(a: string, b: string): LabelContraindication | undefined {
  return BY_PAIR.get([a, b].sort().join("|"));
}

export function labelContraindicationById(id: string): LabelContraindication | undefined {
  return LABEL_CONTRAINDICATIONS.find((r) => r.id === id);
}

/**
 * Bupropion and Contrave labels contraindicate STARTING the drug in a patient
 * being treated with linezolid or intravenous methylene blue (one direction only),
 * so those pins say that instead of a flat "avoid together".
 */
const START_ONLY_LABEL_DRUGS: Record<string, string> = {
  "bupropion": "bupropion",
  "naltrexone-bupropion": "Contrave",
  "fluvoxamine": "fluvoxamine",
  "desvenlafaxine": "Pristiq",
  "duloxetine": "Cymbalta",
  "vortioxetine": "Trintellix",
  "clomipramine": "Anafranil",
  "buspirone": "buspirone",
  "escitalopram": "Lexapro",
  "levomilnacipran": "Fetzima",
  "milnacipran": "Savella",
};
function startOnlySentence(r: LabelContraindication): string | undefined {
  const drug = START_ONLY_LABEL_DRUGS[r.labelDrugId];
  if (!drug || (r.otherId !== "linezolid" && r.otherId !== "methylene-blue")) return undefined;
  const tail = r.origin === "pd"
    ? " The pharmacodynamic finding is held at that level. This is not a CYP grade."
    : !r.enzyme
      ? " This pair has no CYP finding; the label is the reason."
      : "";
  return `The ${r.labelDrug} label lists this under Contraindications in one direction: don't start ${drug} in a patient being treated with linezolid or intravenous methylene blue. This desk shows the pair as Avoid together.${tail}`;
}

/** Plain sentence appended to the pinned finding's clinical text. */
export function labelPinSentence(r: LabelContraindication): string {
  const startOnly = startOnlySentence(r);
  if (startOnly) return startOnly;
  if (r.origin === "pd") {
    return `The ${r.labelDrug} label lists this combination under Contraindications, so this desk shows it as Avoid together. The pharmacodynamic finding is held at that level. This is not a CYP grade.`;
  }
  if (!r.enzyme) {
    return `The ${r.labelDrug} label lists this combination under Contraindications, so this desk shows it as Avoid together. This pair has no CYP finding; the label is the reason.`;
  }
  return `The ${r.labelDrug} label lists this combination under Contraindications, so this desk shows it as Avoid together even where the enzyme grades alone would read lower.`;
}
